import { api } from "../api.js";
import { decide, permissionsOf } from "./access.js";
import { Confirm, runAction } from "./Confirm.js";
import { leave } from "./Notice.js";
import { fillRoute, go, location } from "./router.js";
import { evaluate, forCaller, hidden, isRecord, refusalOf, shown } from "./rules.js";
import { useSession } from "./session.js";
import { say } from "./texts.js";
import { html, reactive, watch } from "./vue.js";

/** A value of a schema as one text, its parts' values in order, as a table's cell shows it. */
function inline(field, value, texts) {
  if (field.parts === undefined) {
    return shown(value, texts);
  }
  const items = field.list === true ? (Array.isArray(value) ? value : []) : isRecord(value) ? [value] : [];
  const text = items
    .filter(isRecord)
    .map((item) =>
      field.parts
        .filter((part) => item[part.name] !== null && item[part.name] !== undefined && item[part.name] !== "")
        .map((part) => inline(part, item[part.name], texts))
        .join(", "),
    )
    .join("; ");
  return text === "" ? say(texts, "screens.none") : text;
}

/**
 * What a view shows of a field: its value as text; a value of a schema
 * part by part; a list of them as a table, a row per item and a column
 * per part.
 */
function drawn(field, value, texts) {
  if (field.parts === undefined) {
    return shown(value, texts);
  }
  const parts = field.parts;
  if (field.list === true) {
    const items = Array.isArray(value) ? value.filter(isRecord) : [];
    if (items.length === 0) {
      return say(texts, "screens.none");
    }
    return html`<table aria-label=${say(texts, field.label)}>
      <thead><tr>${parts.map((part) => html`<th key=${part.name} scope="col">${say(texts, part.label)}</th>`)}</tr></thead>
      <tbody>${items.map((item, index) => html`<tr key=${index}>${parts.map((part) => html`<td key=${part.name}>${inline(part, item[part.name], texts)}</td>`)}</tr>`)}</tbody>
    </table>`;
  }
  if (!isRecord(value)) {
    return say(texts, "screens.none");
  }
  return html`<dl class="screens-parts" aria-label=${say(texts, field.label)}>
    ${parts.map((part) => html`<div key=${part.name}><dt>${say(texts, part.label)}</dt><dd>${drawn(part, value[part.name], texts)}</dd></div>`)}
  </dl>`;
}

export const ViewPage = {
  name: "ViewPage",
  props: {
    schema: { type: Object, required: true },
    texts: { type: Object, required: true },
    routes: { type: Object, required: true },
    /** The page's route parameters. */
    parameters: { type: Object, default: () => ({}) },
  },
  setup(props) {
    const session = useSession();
    const state = reactive({ record: undefined, failed: undefined, reload: 0, confirming: undefined, reason: "", running: false, refused: "" });
    const schema = () => ({ ...props.schema, sections: forCaller(props.schema.sections, permissionsOf(session.value)) });

    watch(
      () => [props.parameters, state.reload],
      () => {
        const { texts } = props;
        const source = props.schema.source;
        const begun = state.reload;
        api
          .call(source.operation, { parameters: props.parameters })
          .then(async (response) => {
            const answer = response.ok ? await api.body(response) : undefined;
            if (begun !== state.reload) {
              return;
            }
            if (typeof answer === "object" && answer !== null) {
              state.record = answer;
            } else {
              state.failed = say(texts, refusalOf(source.failed, response.status)?.message ?? "screens.failed");
            }
          })
          .catch(() => {
            if (begun === state.reload) {
              state.failed = say(texts, "screens.failed");
            }
          });
      },
      { immediate: true, deep: true },
    );

    const holds = (permission) => session.value !== undefined && session.value !== null && decide(permission, session.value) === "allowed";

    async function run(action) {
      if (action.reason !== undefined && state.reason.trim() === "") {
        return;
      }
      state.running = true;
      const answer = await runAction(action, { ...props.parameters, ...state.record }, state.reason, props.texts);
      if (answer === undefined && action.signIn !== undefined) {
        try {
          const { signIn } = await import("../identity-provider.js");
          await signIn();
          return;
        } catch (error) {
          state.refused = error instanceof Error ? error.message : String(error);
        }
      } else if (answer === undefined) {
        state.refused = "";
        if (action.message !== undefined) {
          leave(say(props.texts, action.message), location.value.path);
        }
        state.reload += 1;
      } else {
        state.refused = answer;
      }
      state.running = false;
      state.confirming = undefined;
      state.reason = "";
    }

    function start(action) {
      state.reason = "";
      if (action.confirm === undefined) {
        void run(action);
      } else {
        state.confirming = action;
      }
    }

    return () => {
      const { texts, routes, parameters } = props;
      const page = schema();
      if (state.failed !== undefined) {
        return html`<p role="alert" class="screens-refused">${state.failed}</p>`;
      }
      const record = state.record;
      if (record === undefined) {
        return html`<p role="status" class="screens-loading">${say(texts, "screens.loading")}</p>`;
      }
      const offered = page.actions.filter((action) => holds(action.permission));
      const runs = page.operations.filter((action) => holds(action.permission) && (action.when === undefined || evaluate(action.when, record) === true));
      return html`<section class="screens-view">
        <h1>${say(texts, page.title)}</h1>
        ${state.refused !== "" ? html`<p role="alert" class="screens-problem">${state.refused} <button type="button" class="screens-close" aria-label="×" onClick=${() => (state.refused = "")}>×</button></p>` : null}
        ${page.sections.map(
          (section, index) => html`<div key=${index} class="screens-section">
            ${section.title !== undefined ? html`<h2>${say(texts, section.title)}</h2>` : null}
            <dl aria-label=${section.title === undefined ? say(texts, page.title) : say(texts, section.title)}>
              ${section.fields.filter((field) => !hidden(field, record)).map((field) => html`<div key=${field.name}><dt>${say(texts, field.label)}</dt><dd>${drawn(field, record[field.name], texts)}</dd></div>`)}
            </dl>
          </div>`,
        )}
        ${offered.length + runs.length > 0
          ? html`<div class="screens-buttons">
              ${offered.map((action) => html`<button key=${action.navigate} type="button" class="screens-secondary" onClick=${() => go(fillRoute(routes[action.navigate] ?? "/", { ...parameters, ...record }))}>${say(texts, action.label)}</button>`)}
              ${runs.map((action) => html`<button key=${action.operation} type="button" class=${action.confirm === undefined ? "screens-secondary" : "screens-danger"} disabled=${state.running} onClick=${() => start(action)}>${say(texts, action.label)}</button>`)}
            </div>`
          : null}
        ${state.confirming !== undefined && state.confirming.confirm !== undefined
          ? html`<${Confirm}
              action=${state.confirming}
              texts=${texts}
              reason=${state.reason}
              running=${state.running}
              onReason=${(reason) => (state.reason = reason)}
              onConfirm=${() => void run(state.confirming)}
              onClose=${() => (state.confirming = undefined)}
            />`
          : null}
      </section>`;
    };
  },
};
